sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    //Gliding to custody trade task template table for sla timer field value
    var slaDuration = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_template');
    slaDuration.addQuery('template_short_description', current.short_description);
    slaDuration.query();
    if (slaDuration.next() && slaDuration.sla_timer != ' ') {
        var dys;
        var mins;
        var hrs;
        var secs;
        var slaDisplayValue = slaDuration.sla_timer.getDisplayValue();
        var slaValue = new GlideDateTime(slaDuration.sla_timer);
        //fetching task created sys time
        var dueDate = new GlideDateTime(current.sys_created_on);

        if (slaDisplayValue.contains("Days") || slaDisplayValue.contains("Day")) { //checking whether days are there in display value
            if (slaDisplayValue.contains("Hours") || slaDisplayValue.contains("Hour")) { //checking whether hours are there in display value
                var dateTime = slaDisplayValue.split(' ');
                dys = dateTime[0];
                hrs = dateTime[2];
                mins = dateTime[4];
                secs = slaDuration.sla_timer.slice(-2); //slicing because display value does not contain the seconds
            } 
			else {
                dateTime = slaDisplayValue.split(' ');
                dys = dateTime[0];
                mins = dateTime[2];
                secs = slaDuration.sla_timer.slice(-2); //slicing because display value does not contain the seconds
            }
        } else {
            var date = slaValue.toString().split(" ")[0];
            var time = slaValue.toString().split(" ")[1];

            hrs = time.split(":")[0];
            mins = time.split(":")[1];
            secs = time.split(":")[2];
        }
    }
    if (dys) {
        dueDate.addDaysLocalTime(dys);
    }
    if (hrs) {
        dueDate.addSeconds(3600 * hrs);
    }
    if (mins) {
        dueDate.addSeconds(60 * mins);
    }
    if (secs) {
        dueDate.addSeconds(secs);
    }
	current.due_date = dueDate;
    current.update();
//gs.info('taskSlaTime ' + sla + '\nslaDays ' + dys + '\nslaHours ' + hrs + '\nslaMin ' + mins + '\nslaSeconds ' + secs + '\nDueDate ' + dueDate + '\nCREATEDDATE' + current.sys_created_on);
})(current, previous);
